fn entity_explode<S: EventSession>(s: &S, event: &mut game_event::Explode) -> bool {
    let first = event.entity.as_ref().map(|x0| s.entity(x0));
    let mut stages = Vec::new(); if let Some(first) = &first { stages.push(("explode", Some(Handle::Entity(first.clone())))); } stages.push(("entity_explode", None));
    if !s.listening(&stages) { return false; }
    let payload = shapes::ExplodeEvent {
        entity: first.clone(),
        block: (&event.block).as_ref().map(|x0| s.block(x0)),
        state: (&event.state).as_ref().map(|x0| x0.clone()),
        location: s.location((&event.location)),
        blocks: (&(event.blocks)()).iter().map(|x0| s.block(x0)).collect(),
        breaks_blocks: *(&event.breaks_blocks),
        r#yield: *(&event.r#yield),
    };
    let Some(out) = s.emit(&stages, codecs::ExplodeEvent, payload) else { return false; };
    if let Some(v) = s.read(&out, "breaks_blocks", Bool) { event.breaks_blocks = v; }
    if let Some(v) = s.read(&out, "yield", Num) { event.r#yield = v.clamp(0.0, 1.0); }
    out.cancelled
}

