fn server_list_ping<S: EventSession>(s: &S, event: &mut game_event::ServerListPing) -> bool {
    let stages = [("server_list_ping", None)];
    if !s.listening(&stages) { return false; }
    let payload = shapes::ServerListPingEvent {
        address: (&event.address).clone(),
        description: s.text((&event.description)),
        online: i64::from(*(&event.online)),
        max_players: i64::from(*(&event.max_players)),
        hide_players: *(&event.hide_players),
    };
    let Some(out) = s.emit(&stages, codecs::ServerListPingEvent, payload) else { return false; };
    if let Some(v) = s.read(&out, "description", TextCodec) { event.description = v.0; }
    if let Some(v) = s.read(&out, "online", Int) { event.online = v.clamp(0, i64::from(i32::MAX)) as i32; }
    if let Some(v) = s.read(&out, "max_players", Int) { event.max_players = v.clamp(0, i64::from(i32::MAX)) as i32; }
    if let Some(v) = s.read(&out, "hide_players", Bool) { event.hide_players = v; }
    out.cancelled
}

